SELECT

FROM conversation_item
INNER JOIN chat_conversation
        ON chat_conversation.id = conversation_item.conversation_id
WHERE conversation_item.id = #{id}
  AND chat_conversation.user_id = #{userId}

SELECT COALESCE(MAX(conversation_item.sequence_no), 0)
FROM conversation_item
INNER JOIN chat_conversation
        ON chat_conversation.id = conversation_item.conversation_id
WHERE conversation_item.conversation_id = #{conversationId}
  AND chat_conversation.user_id = #{userId}
